code.cpp:
class Solution {
public:
    int maxNonOverlapping(vector<int>& nums, int target) {
        unordered_set<int> seen;
        seen.insert(0);
        int prefix = 0;
        int count = 0;
        for (int num : nums) {
            prefix += num;
            if (seen.count(prefix - target)) {
                count++;
                seen.clear();
                seen.insert(prefix);
            } else {
                seen.insert(prefix);
            }
        }
        return count;
    }
};
